/* RemediGenius Community Edition — Dashboard tab for the Hermes dashboard.
 * The page is generated by the desk (`rgtriage board --html`) and served by this plugin's backend at
 * /api/plugins/rg-board/page. "Refresh now" is a real scan through the desk, not a page reload: the desk collects
 * every configured source, writes the new board.html and status.json, and the iframe then reloads.
 * No build step: plain React elements from the dashboard SDK. */
(function () {
  "use strict";
  var SDK = window.__HERMES_PLUGIN_SDK__;
  var React = SDK.React;
  var h = React.createElement;
  var useState = SDK.hooks.useState, useEffect = SDK.hooks.useEffect, useRef = SDK.hooks.useRef;
  var API = "/api/plugins/rg-board";

  function get(path) { return SDK.fetchJSON(API + path); }
  function post(path) { return SDK.fetchJSON(API + path, { method: "POST" }); }
  function errText(e) {
    var m = (e && (e.detail || e.message)) || String(e);
    try { var j = JSON.parse(m.slice(m.indexOf("{"))); if (j.detail) return j.detail; } catch (x) { /* plain */ }
    return m.replace(/^Error:\s*/, "");
  }

  function BoardPage() {
    var s = useState(null), status = s[0], setStatus = s[1];
    var b = useState(false), busy = b[0], setBusy = b[1];
    var e = useState(""), err = e[0], setErr = e[1];
    var v = useState(0), version = v[0], setVersion = v[1];
    var last = useRef(null);

    useEffect(function () {
      get("/status").then(function (x) { last.current = x; setStatus(x); setErr(""); })
        .catch(function (x) { setErr(errText(x)); });
    }, [version]);

    // A scan can also come from the six-hourly timer. Poll the snapshot time, and swap the page when it moves.
    useEffect(function () {
      var id = setInterval(function () {
        get("/status").then(function (x) {
          if (last.current && x.scanned_at && x.scanned_at !== last.current.scanned_at) {
            setVersion(function (n) { return n + 1; });
          }
          last.current = x;
          setStatus(x);
        }).catch(function () { /* keep the last good board */ });
      }, 60000);
      return function () { clearInterval(id); };
    }, []);

    function refresh() {
      setBusy(true); setErr("");
      post("/refresh")
        .then(function (x) { last.current = x; setStatus(x); setVersion(version + 1); })
        .catch(function (x) { setErr(errText(x)); setBusy(false); });
    }

    var when = status && status.scanned_at
      ? "scanned " + String(status.scanned_at).replace("T", " ").slice(0, 16) + " UTC · " + status.age
      : (status ? status.age : "loading…");

    return h("div", { className: "rgb-page" },
      h("div", { className: "rgb-bar" },
        h("div", { className: "rgb-title" },
          h("strong", null, "Security attention board"),
          h("span", { className: "rgb-age" }, " · " + when)),
        h("button", { className: "rgb-btn", type: "button", onClick: refresh, disabled: busy,
                      title: "Run a full scan of every configured account, region and source, then reload this page" },
          busy ? "Scanning all sources…" : "Refresh now")),
      err ? h("div", { className: "rgb-err", role: "alert" }, err) : null,
      h("iframe", { className: "rgb-frame", title: "Security attention board",
                    src: API + "/page?v=" + version }));
  }

  window.__HERMES_PLUGINS__.register("rg-board", BoardPage);
})();